 *
 * The grid constants below describe the game's own looting bag interface (clientscript 497) and
 * were first documented by Looting Bag Organizer, Copyright (c) 2026, robrichardson13,
 * BSD 2-Clause. See LICENSE.
 */
package com.lootingbagplus.model;

import java.awt.Rectangle;

/**
 * Pure grid arithmetic for the looting bag's item grid ({@code WildernessLootingbag.ITEMS}):
 * 4 columns by 7 rows, cells 36x32, filled top-left in slot order with an 8px gutter between
 * columns.
 *
 * <pre>
 * x(slot) = (slot % 4) * 44        y(slot) = (slot / 4) * 32
 * </pre>
 *
 * <p>Never hit-tests widget children: the game hides empty cells at 0x0, so every drop target
 * comes from this arithmetic on the canvas bounds of the grid layer instead.
 */
public final class BagGeometry
{
	public static final int COLS = 4;
	public static final int ROWS = 7;
	public static final int SLOTS = COLS * ROWS;
	public static final int CELL_W = 36;
	public static final int CELL_H = 32;
	public static final int PITCH_X = 44;
	public static final int PITCH_Y = 32;

	private BagGeometry()
	{
	}

	/** Grid-local x of a slot's cell. */
	public static int x(int slot)
	{
		return (slot % COLS) * PITCH_X;
	}

	/** Grid-local y of a slot's cell. */
	public static int y(int slot)
	{
		return (slot / COLS) * PITCH_Y;
	}

	/** Canvas rectangle of a slot's cell, given the canvas bounds of the grid layer. */
	public static Rectangle cell(int slot, Rectangle gridBounds)
	{
		return new Rectangle(gridBounds.x + x(slot), gridBounds.y + y(slot), CELL_W, CELL_H);
	}

	/**
	 * The slot whose pitch cell contains the canvas point, or {@code -1} if the point is outside
	 * the 4x7 pitch rectangle. A point in the gutter between columns belongs to the column on its
	 * left, because the divide is by pitch rather than by cell width.
	 */
	public static int slotAt(Rectangle gridBounds, int canvasX, int canvasY)
	{
		int relX = canvasX - gridBounds.x;
		int relY = canvasY - gridBounds.y;

		if (relX < 0 || relY < 0)
		{
			return -1;
		}

		int col = relX / PITCH_X;
		int row = relY / PITCH_Y;

		if (col >= COLS || row >= ROWS)
		{
			return -1;
		}

		return row * COLS + col;
	}
}

/*
 * Copyright (c) 2026, Looting Bag Plus contributors
 * All rights reserved.
 *
 * The slot-pinning model (a sparse list of item ids reserved per display slot) is modelled on
 * the approach of Looting Bag Organizer, Copyright (c) 2026, robrichardson13, BSD 2-Clause.
 * See LICENSE.
 */
package com.lootingbagplus.model;

import java.util.Arrays;

/**
 * The player's chosen arrangement of the looting bag: which item id is pinned to which of the 28
 * display slots. A pin reserves a slot for an item id; slots with no pin are filled automatically
 * (see {@link BagArranger}).
 *
 * <p>Pure data with no RuneLite imports. Persisted as a short comma separated string by
 * {@code BagState}.
 */
public final class BagLayout
{
	public static final int SLOTS = 28;

	/** Marker for "no pin" in the backing array. */
	private static final int FREE = -1;

	private final int[] pins = new int[SLOTS];

	public BagLayout()
	{
		Arrays.fill(pins, FREE);
	}

	/**
	 * @return the item id pinned to {@code slot}, or {@code -1} if the slot has no pin
	 */
	public int pinAt(int slot)
	{
		checkSlot(slot);
		return pins[slot];
	}

	public boolean isPinned(int slot)
	{
		return pinAt(slot) != FREE;
	}

	/**
	 * Pins {@code itemId} to {@code slot}. An id that is not positive frees the slot instead.
	 */
	public void setPin(int slot, int itemId)
	{
		checkSlot(slot);
		pins[slot] = itemId > 0 ? itemId : FREE;
	}

	public void clearPin(int slot)
	{
		checkSlot(slot);
		pins[slot] = FREE;
	}

	/**
	 * Swaps the pins of two slots. Moving an item into an empty slot is a swap with a free pin.
	 */
	public void swap(int a, int b)
	{
		checkSlot(a);
		checkSlot(b);
		int tmp = pins[a];
		pins[a] = pins[b];
		pins[b] = tmp;
	}

	public boolean isEmpty()
	{
		for (int pin : pins)
		{
			if (pin != FREE)
			{
				return false;
			}
		}
		return true;
	}

	public void clear()
	{
		Arrays.fill(pins, FREE);
	}

	public BagLayout copy()
	{
		BagLayout copy = new BagLayout();
		System.arraycopy(pins, 0, copy.pins, 0, SLOTS);
		return copy;
	}

	/**
	 * Compact text form: item ids separated by commas, an empty token for a free slot, trailing
	 * free slots omitted. An all-free layout encodes to the empty string.
	 */
	public String encode()
	{
		int last = SLOTS - 1;
		while (last >= 0 && pins[last] == FREE)
		{
			last--;
		}

		StringBuilder sb = new StringBuilder();
		for (int i = 0; i <= last; i++)
		{
			if (i > 0)
			{
				sb.append(',');
			}
			if (pins[i] != FREE)
			{
				sb.append(pins[i]);
			}
		}
		return sb.toString();
	}

	/**
	 * Inverse of {@link #encode()}. Anything unreadable (null, garbage, too many tokens) is
	 * repaired rather than thrown: unparseable tokens become free slots and extra tokens are
	 * dropped, so a damaged config value can never break the render loop.
	 */
	public static BagLayout decode(String text)
	{
		BagLayout layout = new BagLayout();
		if (text == null || text.isEmpty())
		{
			return layout;
		}

		String[] tokens = text.split(",", -1);
		for (int i = 0; i < tokens.length && i < SLOTS; i++)
		{
			String token = tokens[i].trim();
			if (token.isEmpty())
			{
				continue;
			}
			try
			{
				layout.setPin(i, Integer.parseInt(token));
			}
			catch (NumberFormatException e)
			{
				// leave the slot free
			}
		}
		return layout;
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof BagLayout && Arrays.equals(pins, ((BagLayout) o).pins);
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(pins);
	}

	@Override
	public String toString()
	{
		return "BagLayout[" + encode() + "]";
	}

	private static void checkSlot(int slot)
	{
		if (slot < 0 || slot >= SLOTS)
		{
			throw new IndexOutOfBoundsException("slot " + slot + " out of range [0, " + SLOTS + ")");
		}
	}
}

